// ===== ตั้งค่า Address ของ Seambuffing 2 (แก้ที่นี่ที่เดียว) =====
// ใส่ device แบบ Mitsubishi เช่น "D6100", บิตเช่น "M100" / "X10" / "Y20"
// words: 1 = 16 บิต, 2 = 32 บิต (Mitsubishi เก็บ word ต่ำก่อน)
// div: ตัวหาร เช่น Quantity/Minute เก็บ 4500 = 45.00 -> div 100
// address: null = ยังไม่รู้ (ข้าม) -> ใช้ปุ่ม Scan / ดูบล็อก D6100 ด้านล่างช่วยหา
const TAGS = {
    // บล็อกตามตาราง PLC: D6100 สถานะ | D6102-3 เวลาเดินเครื่อง(วินาที) | D6104-5 เวลาเปิดเครื่อง(วินาที)
    //                    D6106-7 OK ของวัน | D6108-9 รอบมอเตอร์หลัก
    block: { address: "D6100", words: 10 },
    // ---- ยังไม่มีในตาราง: ขอ address จากผู้ทำ PLC แล้วใส่ ----
    total: { address: null, words: 2 },   // Counter รวม (Total goals scored)
    ng:    { address: null, words: 2 },
    speed: { address: null, words: 1, div: 100 },   // Quantity/Minute (ชิ้น/นาที)
};

const out = [];
for (const [topic, t] of Object.entries(TAGS)) {
    if (!t.address) continue;
    const isBit = /^[MXYLBF]/i.test(t.address);
    out.push({ topic, cfg: Object.assign({ bit: isBit }, t),
               address: isBit || (t.words || 1) === 1 ? t.address : t.address + "," + t.words });
}
if (!out.length) { node.status({ fill: "yellow", shape: "ring", text: "ยังไม่ได้ใส่ address" }); return null; }
node.status({ fill: "blue", shape: "dot", text: "อ่าน " + out.length + " ค่า" });
return [out];

// ดึงค่าออกจาก payload ของ Ind MC Read -> array เรียงตาม address
// รองรับ: [..] | {D500:1, D501:2, ...} | {"D500,100":[..]} | {value:..} | ตัวเลข
function vals(p) {
    if (Array.isArray(p)) return p;
    if (p && typeof p === "object") {
        if (p.value !== undefined) return vals(p.value);
        if (p.data !== undefined) return vals(p.data);
        const k = Object.keys(p);
        if (k.length === 1) return vals(p[k[0]]);
        const num = s => { const m = String(s).match(/(\d+)(?:\.(\d+))?$/); return m ? +m[1] : 0; };
        return k.sort((a, b) => num(a) - num(b)).map(x => p[x]);
    }
    return [p];
}

const t = msg.cfg || {};
const arr = vals(msg.payload);
let n;
const w32 = (lo, hi) => (Number(hi) & 0xFFFF) * 65536 + (Number(lo) & 0xFFFF);
if (msg.topic === "block") {                          // D6100-D6109
    if (arr.length < 10) { node.warn("บล็อก D6100 ได้ไม่ครบ: " + JSON.stringify(msg.payload)); return null; }
    const db = flow.get("sb_data") || {};
    db.plcStatus = Number(arr[0]);                     // 1 ว่าง | 2 เดินเครื่อง | 3 ผิดปกติ
    db.runSec = w32(arr[2], arr[3]);
    db.onSec  = w32(arr[4], arr[5]);
    db.ok     = w32(arr[6], arr[7]);
    db.rpm    = w32(arr[8], arr[9]);
    flow.set("sb_data", db); flow.set("sb_lastOk", Date.now());
    node.status({ fill: "green", shape: "dot", text: "สถานะ " + db.plcStatus + " OK " + db.ok + " " + new Date().toLocaleTimeString("en-GB") });
    msg.payload = db; return msg;
}
if (t.bit) n = (arr[0] === true || Number(arr[0]) !== 0) ? 1 : 0;
else if ((t.words || 1) === 2) {
    n = (Number(arr[1]) & 0xFFFF) * 65536 + (Number(arr[0]) & 0xFFFF);   // word ต่ำก่อน
    if (n > 0x7FFFFFFF) n -= 0x100000000;
} else n = Number(arr[0]);
if (t.div) n = n / t.div;
if (!Number.isFinite(n)) { node.warn(msg.topic + " อ่านไม่ได้: " + JSON.stringify(msg.payload)); return null; }

const d = flow.get("sb_data") || {};
switch (msg.topic) {
    case "total": d.total = n; flow.set("sb_lastOk", Date.now()); break;
    case "ok":    d.ok = n; break;
    case "ng":    d.ng = n; break;
    case "speed": d.speed = n; break;
    case "auto":  d.auto = n !== 0; break;
    case "alarm": d.alarm = n !== 0; break;
    default: return null;
}
flow.set("sb_data", d);
node.status({ fill: "green", shape: "dot", text: msg.topic + "=" + n + " " + new Date().toLocaleTimeString("en-GB") });
msg.payload = d;
return msg;

// ดึงค่าออกจาก payload ของ Ind MC Read -> array เรียงตาม address
// รองรับ: [..] | {D500:1, D501:2, ...} | {"D500,100":[..]} | {value:..} | ตัวเลข
function vals(p) {
    if (Array.isArray(p)) return p;
    if (p && typeof p === "object") {
        if (p.value !== undefined) return vals(p.value);
        if (p.data !== undefined) return vals(p.data);
        const k = Object.keys(p);
        if (k.length === 1) return vals(p[k[0]]);
        const num = s => { const m = String(s).match(/(\d+)(?:\.(\d+))?$/); return m ? +m[1] : 0; };
        return k.sort((a, b) => num(a) - num(b)).map(x => p[x]);
    }
    return [p];
}

// แสดงเป็น { D6100: ค่า, ... }
if (msg.payload && typeof msg.payload === "object" && !Array.isArray(msg.payload) && Object.keys(msg.payload).length > 1) return msg;
const v = vals(msg.payload), o = {};
v.forEach((x, i) => o["D" + (6100 + i)] = x);
msg.payload = o;
return msg;

// ค่าตัวอย่าง (ทดสอบเส้นทางไป Dashboard โดยไม่ต้องต่อ PLC)
const t = (flow.get("sb_test") || 2075) + 1; flow.set("sb_test", t);
const w = v => [v & 0xFFFF, v >>> 16];
return [[
    { topic: "block", cfg: {}, payload: [2, 0, ...w(20000), ...w(25000), ...w(t), ...w(1450)] },
    { topic: "total", cfg: { words: 2 }, payload: w(t + 448) },
    { topic: "ng",    cfg: { words: 2 }, payload: w(448) },
    { topic: "speed", cfg: { words: 1, div: 100 }, payload: [4500] }
]];

// สร้าง JSON ส่งไป CounterMachine.aspx (รูปแบบเดียวกับเครื่องฉีด + OK/NG)
const MACHINE  = "SB02";          // หน้าเว็บแสดงเป็น "Seambuffing 2"
const PROCESS  = "Seambuffing";   // แท็บ Process บน MC Monitor
const STALE_MS = 10000;

const d = flow.get("sb_data");
const online = !!d && (Date.now() - (flow.get("sb_lastOk") || 0)) < STALE_MS;

if (online) {
    // แปลงเป็นรหัสสถานะเดียวกับเครื่องฉีด: 4 = Running, 1 = Idle, 18 = Breakdown
    // D6100: 1 ว่าง -> 1 (Idle) | 2 เดินเครื่อง -> 4 (Running) | 3 ผิดปกติ -> 18 (Breakdown)
    const status = d.plcStatus != null ? ({ 1: 1, 2: 4, 3: 18 }[d.plcStatus] ?? 1)
                                       : (d.alarm ? 18 : (d.auto ? 4 : 1));
    const TXT = { 1: "Idle", 4: "Running", 18: "Abnormal" };
    msg.payload = {
        machine: MACHINE, process: PROCESS, online: true, power: "ON",
        status: status, statusText: TXT[status],
        shotCount: d.total ?? null,
        okCount: d.ok ?? null,
        ngCount: d.ng ?? null,
        speedPerMin: d.speed ?? null,
        cycleTime: d.speed > 0 ? Math.round(6000 / d.speed) / 100 : null,   // วินาทีต่อชิ้น
        cavities: 1,
        plcRunSec: d.runSec ?? null,      // D6102 เวลาเดินเครื่องสะสม (วินาที)
        plcOnSec: d.onSec ?? null,        // D6104 เวลาเปิดเครื่องสะสม (วินาที)
        rpm: d.rpm ?? null,               // D6108 รอบมอเตอร์หลัก
        ts: new Date().toISOString()
    };
} else {
    msg.payload = { machine: MACHINE, process: PROCESS, online: false, power: "OFF", ts: new Date().toISOString() };
}
msg.headers = { "Content-Type": "application/json" };
msg.requestTimeout = 4000;
return msg;

// สแกน D register ทีละ 100 ตัว (ช่วงที่อ่านไม่ได้จะถูกข้าม)
const FROM = 0, TO = 12000, STEP = 100;
flow.set("scan_hits", []); flow.set("scan_fail", []);
const out = [];
for (let a = FROM; a < TO; a += STEP) out.push({ topic: "scan", retry: 0, start: a, address: "D" + a + "," + STEP });
node.status({ fill: "blue", shape: "ring", text: "กำลังสแกน " + out.length + " ช่วง..." });
return [out];

// ดึงค่าออกจาก payload ของ Ind MC Read -> array เรียงตาม address
// รองรับ: [..] | {D500:1, D501:2, ...} | {"D500,100":[..]} | {value:..} | ตัวเลข
function vals(p) {
    if (Array.isArray(p)) return p;
    if (p && typeof p === "object") {
        if (p.value !== undefined) return vals(p.value);
        if (p.data !== undefined) return vals(p.data);
        const k = Object.keys(p);
        if (k.length === 1) return vals(p[k[0]]);
        const num = s => { const m = String(s).match(/(\d+)(?:\.(\d+))?$/); return m ? +m[1] : 0; };
        return k.sort((a, b) => num(a) - num(b)).map(x => p[x]);
    }
    return [p];
}

// หา D ที่ค่าใกล้กับตัวเลขบนจอ (แก้ TARGETS ให้ตรงกับจอตอนกด Scan)
const TARGETS = { total: 2523, ok: 2075, ng: 448, speed: 45, rate: 82.2 };
const COUNTER_TOL = 200;
const v = vals(msg.payload).map(x => Number(x) & 0xFFFF);
const found = [];
for (let i = 0; i < v.length; i++) {
    const a = msg.start + i, w = v[i], nx = v[i + 1];
    const cands = [[w, "16bit"]];
    if (nx) cands.push([nx * 65536 + w, "32bit (D" + a + "-D" + (a + 1) + ")"]);
    for (const [name, tv] of Object.entries(TARGETS)) {
        const isCounter = ["total", "ok", "ng"].includes(name);
        for (const [x, kind] of cands)
            for (const div of (isCounter ? [1] : [1, 10, 100]))
                if (x !== 0 && Math.abs(x / div - tv) <= (isCounter ? COUNTER_TOL : 0.6))
                    found.push({ tag: name, address: "D" + a, value: x / div, kind, div });
    }
}
const hits = flow.get("scan_hits") || []; hits.push(...found); flow.set("scan_hits", hits);
node.status({ fill: "green", shape: "dot", text: "เจอ " + hits.length + " (ล่าสุด D" + msg.start + ")" });
if (!found.length) return null;
msg.payload = found;
return msg;

// ช่วงที่ timeout -> ลองใหม่ (สูงสุด 2 ครั้ง) แล้วข้าม
const r = (msg.retry || 0) + 1;
if (r > 2) { const s = flow.get("scan_fail") || []; s.push("D" + msg.start); flow.set("scan_fail", s);
             node.status({ fill: "red", shape: "ring", text: "ข้าม: " + s.join(", ") }); return null; }
return { topic: "scan", retry: r, start: msg.start, address: msg.address };
